/// Wiki page data transfer object for Flutter（知识库浏览）
class WikiPageDto {
  final String id;
  final String slug;
  final String kind;
  final String title;
  final String summary;
  final String contentMd;
  final List<String> tags;
  final List<String> sourceEventIds;
  final PlatformInt64 evidenceCount;
  final String firstSeenAt;
  final String lastSeenAt;
  final String status;
  final String createdAt;
  final String updatedAt;
  final String? sourceUrl;

  /// 来源/用途分区：imported（素材库）/ network（人物项目）/ insight（知识沉淀）/ derivative（派生产物）
  final String area;

  /// 派生产物指向的原页面 slug（仅 derivative 有值）
  final String? basedOn;

  /// 派生产物的加工类型（总结/提炼观点/抖音文案…，仅 derivative 有值）
  final String? contentType;

  /// 最近一次人工编辑正文的时间（非空 ⇔ 该页由人工持有，digest 不整篇覆盖）
  final String? humanEditedAt;

  /// 素材页观点评价：Some("endorse")/Some("reject")/None=未表态（缺省认可）
  final String? opinion;

  const WikiPageDto({
    required this.id,
    required this.slug,
    required this.kind,
    required this.title,
    required this.summary,
    required this.contentMd,
    required this.tags,
    required this.sourceEventIds,
    required this.evidenceCount,
    required this.firstSeenAt,
    required this.lastSeenAt,
    required this.status,
    required this.createdAt,
    required this.updatedAt,
    this.sourceUrl,
    required this.area,
    this.basedOn,
    this.contentType,
    this.humanEditedAt,
    this.opinion,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      slug.hashCode ^
      kind.hashCode ^
      title.hashCode ^
      summary.hashCode ^
      contentMd.hashCode ^
      tags.hashCode ^
      sourceEventIds.hashCode ^
      evidenceCount.hashCode ^
      firstSeenAt.hashCode ^
      lastSeenAt.hashCode ^
      status.hashCode ^
      createdAt.hashCode ^
      updatedAt.hashCode ^
      sourceUrl.hashCode ^
      area.hashCode ^
      basedOn.hashCode ^
      contentType.hashCode ^
      humanEditedAt.hashCode ^
      opinion.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WikiPageDto &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          slug == other.slug &&
          kind == other.kind &&
          title == other.title &&
          summary == other.summary &&
          contentMd == other.contentMd &&
          tags == other.tags &&
          sourceEventIds == other.sourceEventIds &&
          evidenceCount == other.evidenceCount &&
          firstSeenAt == other.firstSeenAt &&
          lastSeenAt == other.lastSeenAt &&
          status == other.status &&
          createdAt == other.createdAt &&
          updatedAt == other.updatedAt &&
          sourceUrl == other.sourceUrl &&
          area == other.area &&
          basedOn == other.basedOn &&
          contentType == other.contentType &&
          humanEditedAt == other.humanEditedAt &&
          opinion == other.opinion;
}
